// Process and validate incoming event
const eventData = $input.first().json;
const { eventType, sessionId, source, payload, priority = 'normal', metadata = {} } = eventData;

// Validate required fields
if (!eventType || !sessionId || !source) {
  throw new Error('Missing required fields: eventType, sessionId, source');
}

// Generate unique event ID
const eventId = `evt_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;

// Event schema validation
const validEventTypes = [
  'player_action',
  'dm_action',
  'combat_event',
  'dialogue_event',
  'system_event',
  'ai_agent_event',
  'voice_event',
  'session_event',
  'error_event'
];

if (!validEventTypes.includes(eventType)) {
  throw new Error(`Invalid event type: ${eventType}`);
}

// Priority validation
const validPriorities = ['low', 'normal', 'high', 'critical'];
if (!validPriorities.includes(priority)) {
  throw new Error(`Invalid priority: ${priority}`);
}

// Create event object
const event = {
  eventId,
  eventType,
  sessionId,
  source, // 'player', 'dm', 'ai_agent', 'system'
  payload,
  priority,
  metadata: {
    ...metadata,
    timestamp: new Date().toISOString(),
    version: '1.0'
  },
  routing: {
    targets: [], // Will be populated by routing logic
    filters: [], // Event filters
    retries: 0,
    maxRetries: 3
  }
};

return { json: event };

// Determine event routing and targets
const eventData = $input.first().json;
const { eventType, sessionId, source, payload } = eventData;

// Get session information
const sessionInfo = await $getGoogleFirestoreItem('game_sessions', sessionId);
const participants = sessionInfo?.players || [];

// Build routing configuration
const routing = {
  ...eventData.routing,
  targets: [],
  filters: buildEventFilters(eventType, payload)
};

// Determine targets based on event type and source
switch (eventType) {
  case 'player_action':
    routing.targets = buildPlayerActionTargets(participants, source, payload);
    break;
  case 'dm_action':
    routing.targets = buildDMActionTargets(participants, payload);
    break;
  case 'combat_event':
    routing.targets = buildCombatEventTargets(participants, payload);
    break;
  case 'dialogue_event':
    routing.targets = buildDialogueEventTargets(participants, payload);
    break;
  case 'system_event':
    routing.targets = buildSystemEventTargets(participants, payload);
    break;
  case 'ai_agent_event':
    routing.targets = buildAIEventTargets(participants, payload);
    break;
  case 'voice_event':
    routing.targets = buildVoiceEventTargets(participants, payload);
    break;
  case 'session_event':
    routing.targets = buildSessionEventTargets(participants, payload);
    break;
  case 'error_event':
    routing.targets = buildErrorEventTargets(participants, payload);
    break;
}

function buildEventFilters(eventType, payload) {
  const filters = [];

  // Add role-based filters
  if (payload.requiresDM) {
    filters.push({ type: 'role', value: 'game_master' });
  }

  if (payload.requiresPlayer) {
    filters.push({ type: 'role', value: 'player' });
  }

  // Add permission-based filters
  if (payload.requiredPermissions) {
    payload.requiredPermissions.forEach(perm => {
      filters.push({ type: 'permission', value: perm });
    });
  }

  return filters;
}

function buildPlayerActionTargets(participants, source, payload) {
  const targets = [];

  // Always include DM
  const dm = participants.find(p => p.role === 'game_master');
  if (dm) {
    targets.push({
      userId: dm.userId,
      type: 'websocket',
      endpoint: `/session/${sessionId}/dm`,
      filters: ['dm_notifications']
    });
  }

  // Include other players (unless private)
  if (!payload.isPrivate) {
    participants
      .filter(p => p.userId !== source && p.role === 'player')
      .forEach(player => {
        targets.push({
          userId: player.userId,
          type: 'websocket',
          endpoint: `/session/${sessionId}/player/${player.userId}`,
          filters: ['player_notifications']
        });
      });
  }

  // Include AI agents if applicable
  if (payload.requiresAIResponse) {
    targets.push({
      type: 'ai_agent',
      endpoint: `/ai/agent/respond`,
      filters: ['ai_processing']
    });
  }

  return targets;
}

function buildDMActionTargets(participants, payload) {
  // DM actions typically broadcast to all players
  return participants
    .filter(p => p.role === 'player')
    .map(player => ({
      userId: player.userId,
      type: 'websocket',
      endpoint: `/session/${sessionId}/player/${player.userId}`,
      filters: ['dm_actions']
    }));
}

function buildCombatEventTargets(participants, payload) {
  const targets = [];

  // Combat events go to all participants in combat
  const combatParticipants = payload.combatParticipants || participants;

  combatParticipants.forEach(participant => {
    targets.push({
      userId: participant.userId,
      type: 'websocket',
      endpoint: `/session/${sessionId}/combat`,
      filters: ['combat_events']
    });
  });

  // Also include AI agents for combat logic
  targets.push({
    type: 'ai_agent',
    endpoint: `/ai/combat/process`,
    filters: ['combat_ai']
  });

  return targets;
}

function buildDialogueEventTargets(participants, payload) {
  const targets = [];

  // Dialogue events go to relevant participants
  if (payload.targetType === 'all') {
    participants.forEach(player => {
      targets.push({
        userId: player.userId,
        type: 'websocket',
        endpoint: `/session/${sessionId}/dialogue`,
        filters: ['dialogue_events']
      });
    });
  } else if (payload.targetType === 'specific' && payload.targetUsers) {
    payload.targetUsers.forEach(targetUserId => {
      const player = participants.find(p => p.userId === targetUserId);
      if (player) {
        targets.push({
          userId: targetUserId,
          type: 'websocket',
          endpoint: `/session/${sessionId}/dialogue`,
          filters: ['dialogue_events']
        });
      }
    });
  }

  return targets;
}

function buildSystemEventTargets(participants, payload) {
  // System events go to all relevant services
  const targets = [];

  // Notify monitoring system
  targets.push({
    type: 'service',
    service: 'monitoring',
    endpoint: '/monitoring/events',
    filters: ['system_events']
  });

  // Notify logging system
  targets.push({
    type: 'service',
    service: 'logging',
    endpoint: '/logging/events',
    filters: ['system_events']
  });

  // If it's user-visible, notify participants
  if (payload.userVisible) {
    participants.forEach(player => {
      targets.push({
        userId: player.userId,
        type: 'websocket',
        endpoint: `/session/${sessionId}/system`,
        filters: ['system_notifications']
      });
    });
  }

  return targets;
}

function buildAIEventTargets(participants, payload) {
  const targets = [];

  // AI events typically go to DM for oversight
  const dm = participants.find(p => p.role === 'game_master');
  if (dm) {
    targets.push({
      userId: dm.userId,
      type: 'websocket',
      endpoint: `/session/${sessionId}/dm`,
      filters: ['ai_events']
    });
  }

  // Also go to AI monitoring service
  targets.push({
    type: 'service',
    service: 'ai_monitoring',
    endpoint: '/ai/monitoring/events',
    filters: ['ai_events']
  });

  return targets;
}

function buildVoiceEventTargets(participants, payload) {
  // Voice events go to participants in voice channel
  const voiceParticipants = participants.filter(p => 
    payload.voiceChannelParticipants?.includes(p.userId)
  );

  return voiceParticipants.map(player => ({
    userId: player.userId,
    type: 'websocket',
    endpoint: `/session/${sessionId}/voice`,
    filters: ['voice_events']
  }));
}

function buildSessionEventTargets(participants, payload) {
  // Session events go to all participants
  return participants.map(player => ({
    userId: player.userId,
    type: 'websocket',
    endpoint: `/session/${sessionId}/session`,
    filters: ['session_events']
  }));
}

function buildErrorEventTargets(participants, payload) {
  const targets = [];

  // Error events go to monitoring and logging
  targets.push({
    type: 'service',
    service: 'monitoring',
    endpoint: '/monitoring/errors',
    filters: ['error_events']
  });

  targets.push({
    type: 'service',
    service: 'logging',
    endpoint: '/logging/errors',
    filters: ['error_events']
  });

  // If user-visible error, notify DM
  if (payload.userVisible) {
    const dm = participants.find(p => p.role === 'game_master');
    if (dm) {
      targets.push({
        userId: dm.userId,
        type: 'websocket',
        endpoint: `/session/${sessionId}/dm`,
        filters: ['error_notifications']
      });
    }
  }

  return targets;
}

return {
  json: {
    ...eventData,
    routing
  }
};

// Filter and route events to targets
const eventData = $input.first().json;
const { eventId, routing, payload, priority } = eventData;

// Apply filters to targets
const filteredTargets = routing.targets.filter(target => {
  if (!target.filters || target.filters.length === 0) {
    return true;
  }

  // Check if event passes all filters for this target
  return target.filters.every(filter => {
    switch (filter.type) {
      case 'role':
        return checkRoleFilter(filter.value, payload);
      case 'permission':
        return checkPermissionFilter(filter.value, payload);
      case 'event_type':
        return checkEventTypeFilter(filter.value, eventData.eventType);
      default:
        return true;
    }
  });
});

function checkRoleFilter(requiredRole, payload) {
  // Check if payload requires specific role
  return payload.requiredRole !== requiredRole;
}

function checkPermissionFilter(requiredPermission, payload) {
  // Check if payload requires specific permission
  return !payload.requiredPermissions || 
         !payload.requiredPermissions.includes(requiredPermission);
}

function checkEventTypeFilter(allowedType, eventType) {
  return eventType === allowedType;
}

// Sort targets by priority
const sortedTargets = filteredTargets.sort((a, b) => {
  const priorityOrder = { critical: 0, high: 1, normal: 2, low: 3 };
  return priorityOrder[priority] - priorityOrder[priority];
});

return sortedTargets.map(target => ({
  json: {
    eventId,
    target,
    eventData,
    attemptNumber: 1
  }
}));

// Track event delivery and handle failures
const deliveryResult = $input.first().json;
const { eventId, target, eventData, attemptNumber } = deliveryResult;

const deliveryRecord = {
  eventId,
  targetId: target.userId || target.service || target.type,
  targetType: target.type,
  endpoint: target.endpoint,
  attemptNumber,
  delivered: true,
  deliveredAt: new Date().toISOString(),
  response: deliveryResult.response || null,
  error: deliveryResult.error || null
};

// Update event delivery status
await $setGoogleFirestoreItem('event_deliveries', `${eventId}_${target.type}_${target.userId || target.service}`, deliveryRecord);

// Update main event record
const eventRecord = await $getGoogleFirestoreItem('events', eventId);
const completedDeliveries = (eventRecord.completedDeliveries || 0) + 1;
const totalTargets = eventRecord.routing.targets.length;

const eventUpdates = {
  completedDeliveries,
  status: completedDeliveries >= totalTargets ? 'completed' : 'processing',
  lastDelivery: new Date().toISOString()
};

await $setGoogleFirestoreItem('events', eventId, eventUpdates);

return {
  json: {
    eventId,
    deliveryRecord,
    progress: {
      completed: completedDeliveries,
      total: totalTargets,
      percentage: Math.round((completedDeliveries / totalTargets) * 100)
    }
  }
};

// Process event subscription request
const subscriptionData = $input.first().json;
const { sessionId, userId, eventTypes, filters = {}, endpoint } = subscriptionData;

// Validate required fields
if (!sessionId || !userId || !eventTypes || !Array.isArray(eventTypes)) {
  throw new Error('Missing required fields: sessionId, userId, eventTypes (array)');
}

// Generate subscription ID
const subscriptionId = `sub_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;

// Create subscription record
const subscription = {
  subscriptionId,
  sessionId,
  userId,
  eventTypes,
  filters,
  endpoint,
  status: 'active',
  createdAt: new Date().toISOString(),
  lastEvent: null,
  eventCount: 0
};

return { json: subscription };

